package com.example.lending;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    void searching_by_part_of_the_title_returns_matching_books() throws Exception {
        registerBook("Quartz Partial Match Guide");

        mockMvc.perform(get("/books").param("title", "Partial Match"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].title").value("Quartz Partial Match Guide"))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"))
                .andExpect(jsonPath("$[0].id").isString());
    }

    @Test
    void searching_ignores_case() throws Exception {
        registerBook("Zephyr Case Insensitive Manual");

        mockMvc.perform(get("/books").param("title", "zephyr CASE insensitive"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].title").value("Zephyr Case Insensitive Manual"));
    }

    @Test
    void searching_returns_every_matching_book() throws Exception {
        registerBook("Nebula Multi Hit Vol 1");
        registerBook("Nebula Multi Hit Vol 2");

        mockMvc.perform(get("/books").param("title", "nebula multi hit"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2));
    }

    @Test
    void searching_without_a_match_returns_an_empty_list() throws Exception {
        mockMvc.perform(get("/books").param("title", "no-such-title-anywhere"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void searching_with_a_blank_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", "  "))
                .andExpect(status().isBadRequest());
    }

    @Test
    void searching_without_a_title_parameter_returns_400() throws Exception {
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private void registerBook(String title) throws Exception {
        mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated());
    }
}
